import json
from pathlib import Path
from urllib.request import Request, build_opener, ProxyHandler, HTTPRedirectHandler
from urllib.error import HTTPError
class NoRedirect(HTTPRedirectHandler):
    def redirect_request(self,*args,**kwargs):
        return None
opener=build_opener(ProxyHandler({}),NoRedirect())
token=Path('/home/admin1/.config/libral-vault/internal-token').read_text().strip()
base='http://127.0.0.1:8791/internal/v1/'
headers={'Authorization':'Bearer '+token,'Content-Type':'application/json'}
with opener.open(Request(base+'health',headers=headers),timeout=10) as r:
    print('VAULT_HEALTH',r.status)
payload={'secret_id':'openrouter-api-key','consumer':'ai-core','url':'https://openrouter.ai/api/v1/key','method':'GET','secret_header':'authorization','secret_prefix':'Bearer '}
try:
    with opener.open(Request(base+'actions/http',headers=headers,data=json.dumps(payload).encode()),timeout=25) as r:
        provider=json.load(r)['provider']
        print('PROVIDER_HTTP',provider['status'])
        if provider['status']==200:
            data=json.loads(provider['body']).get('data',{})
            print('KEY_STATUS',json.dumps({k:data[k] for k in ('limit','limit_remaining','usage','limit_reset','is_free_tier') if k in data}))
except HTTPError as e:
    try:
        err=json.load(e).get('error',{})
        err=err.get('code','UNKNOWN') if isinstance(err,dict) else 'UNKNOWN'
    except (ValueError,TypeError):
        err='UNKNOWN'
    allowed={'HTTP_ORIGIN_NOT_ALLOWED','VAULT_SECRET_NOT_FOUND','VAULT_ACCESS_DENIED','VAULT_SECRET_EXPIRED','INTERNAL_AUTHENTICATION_FAILED','UPSTREAM_TIMEOUT','UPSTREAM_REQUEST_FAILED'}
    print('VAULT_HTTP',e.code,'ERROR',err if err in allowed else 'OTHER')
PY
